import yaml, os

# Load mkdocs.yml
with open('mkdocs.yml') as f:
    config = yaml.safe_load(f)

docs_dir = config.get('docs_dir', 'docs')
exclude = config.get('exclude_docs', '')

# Validate all nav references exist
nav = config.get('nav', [])
errors = []

def check_nav(items):
    for item in items:
        if isinstance(item, dict):
            for label, path in item.items():
                if isinstance(path, str) and path.endswith('.md'):
                    full = os.path.join(docs_dir, path)
                    if not os.path.exists(full):
                        errors.append(f'Missing: {full}')
                elif isinstance(path, list):
                    check_nav(path)

check_nav(nav)

if errors:
    for e in errors:
        print(f'FAIL: {e}')
else:
    print('PASS: All nav references resolve to existing files')

# Validate key config
assert config['site_name'], 'Missing site_name'
assert config['theme']['name'] == 'material', 'Theme not material'
